INSERT INTO `tb_post` VALUES (4,4,2,'面试复盘：MySQL索引被问了30分钟','/imgs/covers/c01.png','从B+树为什么适合磁盘，问到覆盖索引与最左前缀，最后落在一条慢SQL优化上。这场面和在面试经验分享会互练的几乎一模一样，模拟真的有用。',2,104,'2021-12-28 11:50:01','2026-10-17 04:13:00'),(5,1,2,'源码解读局笔记：自动装配三连','/imgs/covers/c02.png','@SpringBootApplication拆成三个注解逐个看，EnableAutoConfiguration、AutoConfigurationImportSelector、spring.factories，一条线串起来就没那么玄学了。',1,0,'2021-12-28 12:57:49','2026-10-17 04:13:00'),(6,10,1,'沙龙听完分享会心得：项目亮点要这样讲','/imgs/covers/c03.png','STAR法则听过无数次，现场看到别人把一次缓存改造讲成完整故事才明白差距在细节：数字、取舍、复盘，一个都不能少。',1,0,'2022-01-11 08:05:47','2026-10-17 04:13:00'),(7,10,1,'算法组第四周：滑动窗口终于通了','/imgs/covers/c04.png','从暴力双循环到窗口收缩模板，五个人互相讲了一遍思路，比刷五十道题有效。下周专题是二分查找的边界条件。',1,0,'2022-01-11 08:05:47','2026-10-17 04:13:00'),(23,4,1010,'Java并发沙龙听完才懂：线程池参数不是背出来的','/imgs/covers/c05.png','讲师把核心线程数讲成常驻员工加临时工的故事，配合队列容量一起看才明白拒绝策略为什么是最后一道闸。现场写了个八线程下载小demo，比看十篇文章都管用。',0,NULL,'2026-09-17 04:49:30','2026-10-17 04:13:00'),(24,4,1010,'第一次去简历门诊，被追着问了三层为什么','/imgs/covers/c06.png','老师只改了三个动词，项目经历立刻有了主线。最扎心的一刀：写了Redis却没讲清楚缓存击穿怎么防。回去把项目重讲了一遍才敢投。',0,NULL,'2026-09-18 09:49:51','2026-10-17 04:13:00'),(25,4,1010,'读完《码农翻身》：从浏览器地址栏重新理解HTTP','/imgs/covers/c07.png','这本书把请求链路拆成小故事，DNS、TCP、HTTP一层层递进，配上读书会现场互相提问，比自学扎实太多。强烈建议组队读。',0,NULL,'2026-09-18 09:49:53','2026-10-17 04:13:00'),(26,4,1010,'系统设计工作坊收获：缓存不只是get和set','/imgs/covers/c08.png','击穿、穿透、雪崩三件套讲完，又加了多级缓存与失效广播的取舍讨论。原来缓存一致性背后是一连串业务权衡。',0,NULL,'2026-09-18 09:49:54','2026-10-17 04:13:00'),(27,3,1010,'组织一场线下沙龙的复盘：运营比写代码难','/imgs/covers/c09.png','报名、签到、物料、议程时间控制，每个环节都有坑。但看到大家散场还在围着白板讨论，值了。下期把时间控制做成倒计时。',0,NULL,'2026-09-18 09:50:03','2026-10-17 04:13:00'),(28,3,1010,'开源第一课：从怯生生提PR到被maintainer点赞','/imgs/covers/c10.png','协作实践局带着走完fork、分支、commit规范、PR描述全流程。原来一个好的PR描述，比代码改得漂亮更重要。',0,NULL,'2026-09-18 09:50:08','2026-10-17 04:13:00'),(29,3,1010,'读书会第二场：技术书要这样读','/imgs/covers/c11.png','先读目录建地图，再精读正文做卡片，最后合上书讲给别人听。费曼学习法在小组里落地，效果拔群。',0,NULL,'2026-09-18 09:50:08','2026-10-17 04:13:00'),(30,3,1010,'JVM案例局笔记：GC日志原来是这么读的','/imgs/covers/c12.png','带着自己的日志现场逐行分析，GC原因、停顿时间、晋升失败一次讲透。回去就把线上服务的监控面板补上了。',0,NULL,'2026-09-18 09:50:08','2026-10-17 04:13:00'),(31,3,1010,'晋升模拟会反馈：你的PPT不是简历','/imgs/covers/c13.png','评委一句话点醒：述职要有主线故事，不是罗列做过什么。把我做了什么改成我解决了什么问题、带来了什么变化，气质完全不同。',0,NULL,'2026-09-18 09:50:27','2026-10-17 04:13:00'),(32,6,1010,'技术英语角：读论文是可以练的技能','/imgs/covers/c14.png','从摘要开始逐句拆解长难句，配上专业词表，两场下来我已经能独立读完一篇MySQL论文的引言部分。第一手信息的世界打开了。',0,NULL,'2026-09-18 09:50:39','2026-10-17 04:13:00'),(33,6,1010,'分布式论文读组：Raft过完第一遍','/imgs/covers/c15.png','Leader选举、日志复制、安全性三章对着动画一起推，现场画状态图。比看视频直观，下周开始讨论工程实现里的坑。',0,NULL,'2026-09-18 09:50:39','2026-10-17 04:13:00'),(34,6,1010,'前后端协作沙龙小记：接口文档即契约','/imgs/covers/c16.png','错误码规范、字段命名、Mock与联调节奏，一场会聊透了协作的边界。回去就给团队整理了一份接口规范模板。',0,NULL,'2026-09-18 09:50:40','2026-10-17 04:13:00'),(35,6,1010,'周末两小时：写了个CLI工具管理沙龙报名','/imgs/covers/c17.png','把签到名单、候补队列、提醒消息串成一条命令，工具效率局的灵感直接落地。下次活动就用它了。',0,NULL,'2026-09-18 09:50:40','2026-10-17 04:13:00'),(36,6,1010,'沙龙前的Redis突击：从背八股到真动手','/imgs/covers/c18.png','为了在沙龙上听懂，突击了持久化、哨兵与Stream。到现场才发现，消息消费组的pending列表才是最好玩的部分。',0,NULL,'2026-09-18 09:50:40','2026-10-17 04:13:00'),(37,2,1010,'写技术博客一年，我是怎么积累个人品牌的','/imgs/covers/c19.png','选题来自日常踩坑，发布节奏比数量重要，评论区是最好的第二课堂。一年下来，面试时被问到博客的场次比简历还多。',0,NULL,'2026-09-18 09:57:16','2026-10-17 04:13:00'),(38,1,1010,'简历门诊专场：老师只改了一个架构图','/imgs/covers/c20.png','把我那张堆满组件的图删到只剩四条链路，面试官三十秒能看懂才算好图。少即是多，讲项目也是同一个道理。',0,NULL,'2026-09-18 09:57:57','2026-10-17 04:13:00');
/*!40000 ALTER TABLE `tb_post` ENABLE KEYS */;
